def solve(I):
    n,m=len(I),len(I[0])
    vals=Counter(v for row in I for v in row); bg=vals.most_common(1)[0][0]
    out=[[0]*m for _ in range(n)]
    # find seeds and axis of alignment
    H,C=set(),set()
    slist=[(r,c,I[r][c]) for r in range(n) for c in range(m) if I[r][c]!=bg]
    if len({s[0] for s in slist})==1:  # vertical line -> perpendicular = horizontal bands
        rs=slist[0][0]; cols={s[1] for s in slist}
        csmin,min2=min(cols); csmax=max(cols)
        # number of bands to span? Demo1: seeds at rows 3 and 7; output rows 2-8 (each seed gets 3 rows).
